INSERT INTO emc_operations_event (event_id, definition_code, job_no, equipment_id, lot_id, length_m, time_min, comment_text, status, registered_by) VALUES (gen_random_uuid(), ?, NULLIF(?, ''), NULLIF(?, ''), NULLIF(?, ''), CAST(NULLIF(CAST(? AS VARCHAR), '') AS NUMERIC), CAST(NULLIF(CAST(? AS VARCHAR), '') AS NUMERIC), NULLIF(?, ''), CASE WHEN ? = 'AVAILABILITY' THEN 'OPEN' ELSE 'CLOSED' END, NULLIF(?, ''))
